function hexToRgb(h){h=h.replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16));}
function blend(fg, bg, a){return fg.map((c,i)=>Math.round(c*a+bg[i]*(1-a)));}
function lum([r,g,b]){const s=[r,g,b].map(v=>{v/=255; return v<=0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055,2.4)}); return 0.2126*s[0]+0.7152*s[1]+0.0722*s[2];}
function contrast(a,b){const L1=lum(a),L2=lum(b); const hi=Math.max(L1,L2), lo=Math.min(L1,L2); return (hi+0.05)/(lo+0.05);}
const panel=hexToRgb('#11182d');
const bg=hexToRgb('#090d19');
const border=hexToRgb('#a6b5ff');
for(const alpha of [0.2,0.3,0.35,0.4,0.45,0.5,0.6,0.7,0.8,1]){
  const b=blend(border,panel,alpha);
  console.log(alpha, b, 'contrast panel', contrast(b,panel).toFixed(2), 'contrast bg', contrast(b,bg).toFixed(2));
}
